inline ::flatbuffers::Offset<TMX> CreateTMX(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    ::flatbuffers::Offset<::flatbuffers::String> RUN_ID = 0,
    ::flatbuffers::Offset<::flatbuffers::String> CREATED_UTC = 0,
    ::flatbuffers::Offset<::flatbuffers::String> WINDOW_START = 0,
    ::flatbuffers::Offset<::flatbuffers::String> WINDOW_END = 0,
    tmxPropagatorKind PROPAGATOR = tmxPropagatorKind_SDN_AP,
    ::flatbuffers::Offset<::flatbuffers::String> PROPAGATOR_ID = 0,
    tmxExecutionHostKind EXECUTION_HOST = tmxExecutionHostKind_BROWSER_LOCAL,
    ::flatbuffers::Offset<::flatbuffers::String> SCORING_PROFILE_ID = 0,
    uint32_t CHUNK_INDEX = 0,
    bool IS_FINAL_CHUNK = true,
    ::flatbuffers::Offset<TMXRequest> REQUEST = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<TMXPhenomenologyWeight>>> PHENOMENOLOGY_WEIGHTS = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<TMXCompoundRule>>> COMPOUND_MULTIPLIERS = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<TMXBucket>>> TARGET_BUCKETS = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<TMXModuleRun>>> PHENOMENOLOGIES_RUN = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<TMXCell>>> CELLS = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<TMXCompoundEvent>>> COMPOUND_EVENTS = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<TMXRollup>>> ROLLUPS = 0) {
  TMXBuilder builder_(_fbb);
  builder_.add_ROLLUPS(ROLLUPS);
  builder_.add_COMPOUND_EVENTS(COMPOUND_EVENTS);
  builder_.add_CELLS(CELLS);
  builder_.add_PHENOMENOLOGIES_RUN(PHENOMENOLOGIES_RUN);
  builder_.add_TARGET_BUCKETS(TARGET_BUCKETS);
  builder_.add_COMPOUND_MULTIPLIERS(COMPOUND_MULTIPLIERS);
  builder_.add_PHENOMENOLOGY_WEIGHTS(PHENOMENOLOGY_WEIGHTS);
  builder_.add_REQUEST(REQUEST);
  builder_.add_CHUNK_INDEX(CHUNK_INDEX);
  builder_.add_SCORING_PROFILE_ID(SCORING_PROFILE_ID);
  builder_.add_PROPAGATOR_ID(PROPAGATOR_ID);
  builder_.add_WINDOW_END(WINDOW_END);
  builder_.add_WINDOW_START(WINDOW_START);
  builder_.add_CREATED_UTC(CREATED_UTC);
  builder_.add_RUN_ID(RUN_ID);
  builder_.add_IS_FINAL_CHUNK(IS_FINAL_CHUNK);
  builder_.add_EXECUTION_HOST(EXECUTION_HOST);
  builder_.add_PROPAGATOR(PROPAGATOR);
  return builder_.Finish();
}

